using System;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;
public static class MobileDockScaleAcceptance {
 public static object Main(){
  if(!UnityEditor.EditorApplication.isPlaying)throw new Exception("Play required");
  const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
  var t=typeof(EchoSphere.Runtime.EchoSphereRuntime).Assembly.GetType("EchoSphere.Presentation.NativeMobileControlsView");var stateType=t.GetNestedType("State",BindingFlags.NonPublic);var controlType=t.GetNestedType("Control",BindingFlags.NonPublic);
  int checks=0;void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
  void Set(object o,string key,object value)=>o.GetType().GetField(key,F).SetValue(o,value);
  object State(bool ru,bool right,int abilities){var state=Activator.CreateInstance(stateType,true);Set(state,"Right",right);Set(state,"Name",ru?"Стандартная сфера":"Standard sphere");Set(state,"Description",ru?"Универсальная сфера со сбалансированными характеристиками.":"Universal sphere with balanced characteristics.");var list=(System.Collections.IList)stateType.GetField("Controls",F).GetValue(state);
   void Add(string id,string name,string detail=null,string icon=null,bool active=false,bool disabled=false){var c=Activator.CreateInstance(controlType,true);Set(c,"Id",id);Set(c,"Name",name);Set(c,"Detail",detail);Set(c,"Icon",icon);Set(c,"Color","#63e6ff");Set(c,"Active",active);Set(c,"Disabled",disabled);list.Add(c);}
   Add("pause",null,icon:"Pause");Add("lock",ru?"Перенос":"Move",ru?"Стоп":"Locked",icon:"Lock",active:true);Add("follow",ru?"Следом":"Follow",abilities%2==1?"100%":(ru?"Выкл":"Off"),icon:"Move",active:abilities%2==1,disabled:abilities%2==0);
   for(int i=0;i<abilities;i++)Add("ability:"+i+"-blast",ru?"Цепная молния":"Chain lightning",ru?"Готово":"Ready");Add("dash",ru?"Рывок":"Dash",ru?"Рывок: 12с":"Dash: 12s",icon:"Zap");
   foreach(var id in new[]{"standard","sniper","shotgun","chain","aura","fire","ice","poison","lightning","energy"})Add("sphere:"+id,null,active:id=="standard");return state;
  }
  var go=new GameObject("Dock grid and scale acceptance");var panel=ScriptableObject.CreateInstance<PanelSettings>();panel.scaleMode=PanelScaleMode.ConstantPixelSize;panel.themeStyleSheet=Resources.Load<ThemeStyleSheet>("EchoSphere/SourceUiTheme");panel.sortingOrder=2500;var rt=new RenderTexture(1080,2400,24);rt.Create();panel.targetTexture=rt;var doc=go.AddComponent<UIDocument>();doc.panelSettings=panel;var parent=doc.rootVisualElement;parent.style.width=390;parent.style.height=873;parent.style.backgroundColor=new Color(.02f,.04f,.07f,1);
  var host=new VisualElement();host.style.position=Position.Absolute;host.style.bottom=16;parent.Add(host);int bindings=0;object view=Activator.CreateInstance(t,F,null,new object[]{host,(Action<Button,string>)((_,id)=>bindings++)},null);var root=(VisualElement)t.GetProperty("Root",F).GetValue(view);
  var cases=(from dpr in new[]{1f,1.75f,2.75f} from scale in new[]{.75f,1f,1.25f} from ru in new[]{true,false} from right in new[]{false,true} from abilities in new[]{0,1,2,3} select new{dpr,scale,ru,right,abilities}).ToArray();int stage=0,frames=0,last=-1;bool background=Application.runInBackground;Application.runInBackground=true;double deadline=UnityEditor.EditorApplication.timeSinceStartup+240;var rows=new List<object>();var stableHeights=new Dictionary<string,float>();
  void Bind(){var c=cases[stage];panel.scale=c.dpr;host.style.left=c.right?new StyleLength(StyleKeyword.Auto):12;host.style.right=c.right?12:new StyleLength(StyleKeyword.Auto);host.style.scale=new Scale(new Vector3(c.scale,c.scale,1));host.style.transformOrigin=new TransformOrigin(Length.Percent(c.right?100:0),Length.Percent(100));t.GetMethod("Bind",F).Invoke(view,new[]{State(c.ru,c.right,c.abilities)});root.style.position=Position.Relative;root.style.opacity=1;frames=0;}
  UnityEditor.EditorApplication.CallbackFunction tick=null;
  void Finish(string result){UnityEditor.EditorApplication.update-=tick;((IDisposable)view).Dispose();panel.targetTexture=null;UnityEngine.Object.Destroy(go);UnityEngine.Object.Destroy(panel);rt.Release();UnityEngine.Object.Destroy(rt);Application.runInBackground=background;var json=Newtonsoft.Json.JsonConvert.SerializeObject(new{result,checks,bindings,rows,scope="Real UI Toolkit grid, bounds and text; source 44px buttons, 6px gap, five columns, 244x94 CSS at all densities; ergonomic controls preserve input IDs."});System.IO.File.WriteAllText(System.IO.Path.Combine(Application.dataPath,"../Library/mobile-dock-scale-acceptance.json"),json);UnityEditor.SessionState.SetString("EchoMobileDockScale",json);}
  Bind();tick=()=>{try{UnityEditor.EditorApplication.QueuePlayerLoopUpdate();if(!UnityEditor.EditorApplication.isPlaying||UnityEditor.EditorApplication.timeSinceStartup>deadline)throw new Exception("Play/deadline");if(last==Time.frameCount)return;last=Time.frameCount;if(++frames<5)return;var c=cases[stage];var palette=root.Q("spheres");var sphereRows=palette.Children().ToArray();Check(sphereRows.Length==2,"Palette must have exactly two rows");Check(Math.Abs(palette.layout.width-244)<.1f&&Math.Abs(palette.layout.height-94)<=2/c.dpr,"Source palette geometry changed: "+palette.layout);
   foreach(var row in sphereRows){Check(row.childCount==5,"Sphere row must have five controls");foreach(var child in row.Children()){Check(Math.Abs(child.layout.width-44)<=1/c.dpr&&Math.Abs(child.layout.height-44)<=1/c.dpr,"Source sphere size changed");Check(child.worldBound.xMin>=palette.worldBound.xMin-.5f&&child.worldBound.xMax<=palette.worldBound.xMax+.5f,"Sphere overflow");}}
   Check(Math.Abs(palette.worldBound.width-244*c.scale)<.6f,"Interface scale applied incorrectly");Check(root.worldBound.xMin>=-.5&&root.worldBound.xMax<=390.5,"Dock outside portrait screen");
   var actions=root.Q("abilities");Check(actions.childCount==(c.abilities+2)/2,"Action rows differ from two-column grid");foreach(var row in actions.Children())Check(row.childCount<=2,"Action grid overflow");
   foreach(var label in root.Query<Label>().ToList()){Button button=null;for(var p=label.parent;p!=null;p=p.parent)if(p is Button b){button=b;break;}if(button==null)continue;Check(label.worldBound.xMin>=button.worldBound.xMin-.5&&label.worldBound.xMax<=button.worldBound.xMax+.5&&label.worldBound.yMin>=button.worldBound.yMin-.5&&label.worldBound.yMax<=button.worldBound.yMax+.5,"Text outside button "+button.name+"/"+label.name);if(!button.name.Contains("ability:")){var full=label.MeasureTextSize(label.text??"",0,VisualElement.MeasureMode.Undefined,0,VisualElement.MeasureMode.Undefined);Check(full.x<=label.contentRect.width+1,"Full control label clipped: "+label.text+" wanted "+full.x+" available "+label.contentRect.width);}}
   var heightKey=c.dpr+"/"+c.scale+"/"+c.ru+"/"+c.right+"/"+((c.abilities+2)/2);if(stableHeights.TryGetValue(heightKey,out var expectedHeight))Check(Math.Abs(root.worldBound.height-expectedHeight)<1,"Follow/strain state moved the controls");else stableHeights[heightKey]=root.worldBound.height;rows.Add(new{c.dpr,c.scale,c.ru,c.right,c.abilities,paletteWidth=palette.worldBound.width,paletteHeight=palette.worldBound.height,dockHeight=root.worldBound.height});if(++stage==cases.Length){Finish("PASS");return;}Bind();
  }catch(Exception e){Finish("FAIL "+e);}};UnityEditor.SessionState.SetString("EchoMobileDockScale","RUNNING");UnityEditor.EditorApplication.update+=tick;return new{result="Started",cases=cases.Length};
 }
}
